window.NABH_DATA = {"chapters":{"AAC":{"code":"AAC","name":"Access, Assessment and Continuity of Care","standards":[{"code":"AAC.1","text":"Display of information in the hospital","elements":[{"letter":"a","category":"Commitment","text":"Types of medical care provided at the hospital must meet the needs of the community.","sop":false},{"letter":"b","category":"Commitment","text":"All types of IP, OP, critical and emergency care shall be provided by the clinical departments declared available in the hospital, along with diagnostic and treatment support.","sop":false},{"letter":"c","category":"Commitment","text":"All the departmental functions are defined.","sop":true},{"letter":"d","category":"Commitment","text":"All the departments and medical care available in the hospital are displayed.","sop":false}]},{"code":"AAC.2","text":"The check-in and check-out process must be defined","elements":[{"letter":"a","category":"Commitment","text":"The organisation has a documented protocol guiding the checking in and out of patients within the hospital.","sop":true},{"letter":"b","category":"CORE","text":"All patients under the care of the organisation must be identified by their unique registration number.","sop":false},{"letter":"c","category":"Commitment","text":"A patient must be admitted within the organisation only if the care they need can be provided there.","sop":false},{"letter":"d","category":"Commitment","text":"There must be a documented protocol guiding how existing and new patients are handled when beds are not available.","sop":true},{"letter":"e","category":"Achievement","text":"The type of medical care made available to patients must be based on their clinical condition and clinical requirements.","sop":true}]},{"code":"AAC.3","text":"Patient transfers and referrals are handled effectively","elements":[{"letter":"a","category":"Commitment","text":"Patient transfer into the hospital is handled effectively.","sop":true},{"letter":"b","category":"Commitment","text":"Patient referral or transfer outside the hospital must also be handled effectively.","sop":true},{"letter":"c","category":"Commitment","text":"Staff assisting the patient must be clinically appropriate to the patient's condition.","sop":false},{"letter":"d","category":"Commitment","text":"The organisation must provide a discharge summary at the time of transfer or referral outside.","sop":false}]},{"code":"AAC.4","text":"All patients under the organisation's care must undergo a preliminary assessment","elements":[{"letter":"a","category":"CORE","text":"Preliminary assessments are done in a documented format in all applicable areas.","sop":true},{"letter":"b","category":"Commitment","text":"Only authorised persons must perform the preliminary assessment.","sop":true},{"letter":"c","category":"Commitment","text":"The preliminary assessment must be done within a defined time frame based on the patient's condition and requirements.","sop":true},{"letter":"d","category":"Commitment","text":"IP and day care patient assessment must also include an assessment done by the nursing staff upon admission.","sop":false},{"letter":"e","category":"CORE","text":"Based on the preliminary assessment, a care plan must be documented.","sop":false},{"letter":"f","category":"Achievement","text":"The established treatment plan must be reviewed and authorised by the primary consultant.","sop":false},{"letter":"g","category":"Excellence","text":"The treatment plan must also cover the post-discharge care requirements for the patient.","sop":false}]},{"code":"AAC.5","text":"Patients are assessed during their treatment at defined intervals","elements":[{"letter":"a","category":"CORE","text":"Once the treatment plan is approved and started, patients are reviewed for their response to treatment and improvement.","sop":false},{"letter":"b","category":"Commitment","text":"Out-patients are reassessed on their follow-up dates, which are informed to them at the time of their first OP visit.","sop":false},{"letter":"c","category":"Commitment","text":"If needed, the care plan is altered to fit the current clinical status of the patient.","sop":false},{"letter":"d","category":"Commitment","text":"Regular assessment during the course of treatment must be done only by the staff assigned to the patient.","sop":false},{"letter":"e","category":"Commitment","text":"There shall be a documented way of identifying early changes in patient status that require prompt action or a change of care.","sop":true}]},{"code":"AAC.6","text":"Hospital-provided laboratory services align with the hospital's defined medical care","elements":[{"letter":"a","category":"Commitment","text":"Lab services provided must align with the hospital's displayed clinical care.","sop":false},{"letter":"b","category":"Commitment","text":"Both technical and equipment infrastructure are made available to provide the said lab services.","sop":false},{"letter":"c","category":"Commitment","text":"Adequate staffing is made available for the laboratory.","sop":false},{"letter":"d","category":"Commitment","text":"All investigations and result reporting are done only by authorised and trained staff.","sop":false},{"letter":"e","category":"Commitment","text":"Written guidance must assist how the lab functions and its daily operations, from receiving the request to reporting the result to disposing of the specimen.","sop":true},{"letter":"f","category":"Commitment","text":"Lab reports are issued at regular defined time intervals.","sop":true},{"letter":"g","category":"Commitment","text":"Any critically important values are intimated to the primary consultant as soon as possible.","sop":true},{"letter":"h","category":"Commitment","text":"An established format is available to report results.","sop":false},{"letter":"i","category":"Achievement","text":"If there is any discrepancy in the reported results, the lab must have a way to recall the reported results.","sop":true},{"letter":"j","category":"Commitment","text":"Tests not performed within the organisation can be outsourced, provided the outsourcing agency's quality and authorisation are made available.","sop":true}]},{"code":"AAC.7","text":"There is a quality control programme for the laboratory","elements":[{"letter":"a","category":"Commitment","text":"The lab function and quality check are carried out.","sop":true},{"letter":"b","category":"Commitment","text":"The quality check ensures the quality of lab reports through internal quality audit.","sop":true},{"letter":"c","category":"Commitment","text":"The lab allows external quality audit to be carried out.","sop":false},{"letter":"d","category":"Excellence","text":"The quality programme participates in lab meetings wherever applicable.","sop":false},{"letter":"e","category":"Commitment","text":"Lab safety measures are in place.","sop":true},{"letter":"f","category":"Commitment","text":"All staff working in the lab must be trained on their duties.","sop":false},{"letter":"g","category":"Commitment","text":"They are provided with all safety measures.","sop":false}]},{"code":"AAC.8","text":"The hospital provides imaging facilities based on its available clinical services","elements":[{"letter":"a","category":"CORE","text":"Legal clearance is available to provide imaging services.","sop":false},{"letter":"b","category":"Commitment","text":"The types of imaging provided align with the hospital's available clinical services.","sop":false},{"letter":"c","category":"Commitment","text":"All associated facilities, including technical and technological infrastructure, are made available to the imaging services.","sop":false},{"letter":"d","category":"Commitment","text":"Only persons trained for the purpose are authorised to perform the imaging services.","sop":false},{"letter":"e","category":"Commitment","text":"Reports are provided as early as possible or within a defined time frame.","sop":true},{"letter":"f","category":"Commitment","text":"Any important reports are shared with the respective primary consultant at the earliest.","sop":true},{"letter":"g","category":"Commitment","text":"An established format is available to report imaging results.","sop":false},{"letter":"h","category":"Achievement","text":"If there is any discrepancy in the reported results, the imaging department must have a way to recall the reported results.","sop":true},{"letter":"i","category":"Commitment","text":"Tests not performed within the organisation can be outsourced, provided the outsourcing agency's quality and authorisation are made available.","sop":false}]},{"code":"AAC.9","text":"There is a quality control programme for the imaging department","elements":[{"letter":"a","category":"Commitment","text":"The imaging quality control measure is in place.","sop":true},{"letter":"b","category":"Achievement","text":"There is a mechanism to check the correctness of the imaging done specific to the patient's diagnosis.","sop":false},{"letter":"c","category":"Achievement","text":"The quality control includes internal and external auditing of the sample reports.","sop":false},{"letter":"d","category":"Excellence","text":"The department participates in meetings wherever applicable.","sop":false},{"letter":"e","category":"Commitment","text":"Any CAPA required is done and documented.","sop":true},{"letter":"f","category":"Commitment","text":"Safety during radiation is ensured.","sop":true},{"letter":"g","category":"Commitment","text":"Patients are screened before the procedure.","sop":false},{"letter":"h","category":"Commitment","text":"Radiation safety devices are worn by the staff working in it.","sop":false},{"letter":"i","category":"Commitment","text":"The devices used are calibrated and tested to measure the user's exposure to radiation.","sop":true},{"letter":"j","category":"Commitment","text":"Training is provided regarding imaging safety.","sop":false},{"letter":"k","category":"Commitment","text":"Proper display and directions are made available for the radiology department.","sop":false}]},{"code":"AAC.10","text":"Patient care is always provided at all levels","elements":[{"letter":"a","category":"Commitment","text":"A qualified person is available at all clinical levels to provide optimal patient care.","sop":false},{"letter":"b","category":"Commitment","text":"Patient care is available everywhere within the organisation.","sop":false},{"letter":"c","category":"Commitment","text":"Information about the patient is shared between related clinical staff when necessary.","sop":false},{"letter":"d","category":"CORE","text":"Information handover between shifts and between wards is done under a documented mechanism.","sop":false},{"letter":"e","category":"Commitment","text":"Safe transfer of patients between wards is ensured.","sop":false},{"letter":"f","category":"Commitment","text":"Documented guidance shall be present when referring patients to other departments or consultants.","sop":true},{"letter":"g","category":"Achievement","text":"There must be defined timelines and deadlines for all services provided, and in case of any alteration in the time frame, the same shall be communicated to the respective departments or to the patient and family wherever necessary.","sop":false},{"letter":"h","category":"Excellence","text":"The organisation must have a way to ensure the alerted critical value has been acknowledged and the emergency response is carried out.","sop":false}]},{"code":"AAC.11","text":"Safe preventive and promotive health activities are carried out","elements":[{"letter":"a","category":"Commitment","text":"The preventive and promotive healthcare activities are carried out and align with hospital functions.","sop":true},{"letter":"b","category":"Commitment","text":"Non-communicable disease management and screening are done appropriately as per age.","sop":false},{"letter":"c","category":"Commitment","text":"Mental health support and advisories are provided effectively to patients who need them.","sop":false},{"letter":"d","category":"Commitment","text":"Immunisation for both adults and children is advised and handled appropriately when necessary.","sop":false},{"letter":"e","category":"Commitment","text":"Education on lifestyle modifications is provided appropriately.","sop":false}]},{"code":"AAC.12","text":"The discharge and check-out process is available and standardised across the organisation","elements":[{"letter":"a","category":"Commitment","text":"Discharge of the patient is decided with inputs from the consultant, patient and family members.","sop":false},{"letter":"b","category":"Commitment","text":"Inputs from all concerned departments must be obtained before discharging the patient; this includes medico-legal and absconded cases too.","sop":true},{"letter":"c","category":"Commitment","text":"LAMA discharges follow a documented protocol guidance.","sop":true},{"letter":"d","category":"Commitment","text":"LAMA patients must also receive a discharge summary.","sop":false},{"letter":"e","category":"Achievement","text":"A discharge, once planned, must stick to the time frame.","sop":false},{"letter":"f","category":"Achievement","text":"If possible, domiciliary visits are provided following the discharge.","sop":false},{"letter":"g","category":"Commitment","text":"The organisation tracks the discharge time against its benchmarks and takes actions to correct the process if necessary.","sop":false}]},{"code":"AAC.13","text":"Discharge summary content follows an established format defined by the organisation","elements":[{"letter":"a","category":"Commitment","text":"All patients receive a discharge summary.","sop":false},{"letter":"b","category":"Commitment","text":"The contents of the summary must be standardised.","sop":false},{"letter":"c","category":"Commitment","text":"The content in the discharge summary includes follow-up advice, medication and other information in a standardised format.","sop":false},{"letter":"d","category":"Commitment","text":"The summary must also mention the contact information and guidance on how and when to access emergency care if needed.","sop":false},{"letter":"e","category":"Commitment","text":"Death summaries must state the cause of death.","sop":false}]}]},"COP":{"code":"COP","name":"Care of Patients","standards":[{"code":"COP.1","text":"Uniform Care Delivery & Clinical Protocols","elements":[{"letter":"a","category":"Commitment","text":"Equal and rational care must be provided to every patient of the organisation, guided by a documented protocol.","sop":true},{"letter":"b","category":"CORE","text":"A minimum of two identifiers must be used to identify a patient correctly.","sop":false},{"letter":"c","category":"Commitment","text":"To give uniform care, the organisation must follow established evidence based clinical practice guidelines.","sop":false},{"letter":"d","category":"Excellence","text":"There shall be an established clinical care pathway across the organisation, monitored constantly and updated periodically.","sop":false},{"letter":"e","category":"Excellence","text":"Where multi-speciality care is needed, it must be designed, implemented and followed uniformly across the organisation, as per the guiding parameters.","sop":false},{"letter":"f","category":"Commitment","text":"Consultation by telephone or online must be delivered safely, under documented guidance.","sop":true}]},{"code":"COP.2","text":"Emergency Services & Triage Controls","elements":[{"letter":"a","category":"Commitment","text":"The organisation must provide a dedicated area for patients who need immediate care, and easy access to it.","sop":false},{"letter":"b","category":"Achievement","text":"A crowd management system, and the measures that support it, must be in place.","sop":false},{"letter":"c","category":"CORE","text":"Documented procedural guidance must be present for giving emergency services to every case, including those that carry medico-legal considerations.","sop":true},{"letter":"d","category":"Commitment","text":"Patients shall be categorised by their condition, so that their care can be prioritised accordingly.","sop":true},{"letter":"e","category":"Commitment","text":"Every patient under emergency care must be re-evaluated at periodic intervals, to check the response to the care proposed.","sop":false},{"letter":"f","category":"Commitment","text":"Documentation must be in place for admitting a patient, for discharging one after the appropriate treatment has been given, and for moving one home or to another organisation.","sop":false},{"letter":"g","category":"Commitment","text":"On discharge or transfer, a summary of the treatment given must be handed to the patient's side.","sop":false},{"letter":"h","category":"Achievement","text":"There shall be a quality assurance programme to monitor, evaluate and improve the quality of emergency care.","sop":true},{"letter":"i","category":"Commitment","text":"There must be a documented system for a patient who has died, or who may die within minutes of being received.","sop":true}]},{"code":"COP.3","text":"Ambulance Services & Transit Readiness","elements":[{"letter":"a","category":"Commitment","text":"The organisation must have ambulance services appropriate to the areas of service it has established.","sop":false},{"letter":"b","category":"Commitment","text":"The ambulance must be spacious enough to accommodate the patient inside it.","sop":false},{"letter":"c","category":"Commitment","text":"The ambulance provided must meet the needs and the demands of the organisation.","sop":false},{"letter":"d","category":"Commitment","text":"Only trained professionals shall be allowed to operate the ambulance.","sop":false},{"letter":"e","category":"Commitment","text":"Functional performance, emergency medication, medical equipment and every other necessary parameter must be checked daily.","sop":false},{"letter":"f","category":"Commitment","text":"There must be a proper facility for communication.","sop":true},{"letter":"g","category":"Achievement","text":"The emergency department prepares itself to begin treatment early, as soon as the patient is received into the organisation.","sop":false}]},{"code":"COP.4","text":"Disaster Preparedness & Surge Response","elements":[{"letter":"a","category":"Commitment","text":"Potential emergencies and outbreaks in the community shall first be identified by the organisation.","sop":true},{"letter":"b","category":"Commitment","text":"A documented mitigation plan must be available for handling such emergencies and outbreaks.","sop":true},{"letter":"c","category":"Commitment","text":"The organisation must make sure the necessary equipment and products are available during such an emergency.","sop":false},{"letter":"d","category":"Commitment","text":"The mitigation strategies developed should be given a test run at least twice a year.","sop":false}]},{"code":"COP.5","text":"Cardiopulmonary Resuscitation & Code Blue","elements":[{"letter":"a","category":"Commitment","text":"Resuscitation services must be available to patients at all times.","sop":false},{"letter":"b","category":"Commitment","text":"Roles and responsibilities must be assigned to the members allocated to resuscitation services.","sop":false},{"letter":"c","category":"Commitment","text":"Emergency life saving medication must be available in every clinical area of the organisation, at all times.","sop":false},{"letter":"d","category":"Commitment","text":"Resuscitation events must be recorded.","sop":false},{"letter":"e","category":"Commitment","text":"The records and the findings of resuscitation events shall be reviewed and analysed by a dedicated team.","sop":false},{"letter":"f","category":"Commitment","text":"Every finding identified must be rectified, so that it does not recur.","sop":false}]},{"code":"COP.6","text":"Nursing Care Delivery & Staffing","elements":[{"letter":"a","category":"Commitment","text":"Written guidance must support the nursing care given in the organisation.","sop":true},{"letter":"b","category":"Commitment","text":"Nurses must be allocated to patients in accordance with good nursing practice.","sop":false},{"letter":"c","category":"Achievement","text":"That allocation must depend on the condition and the vulnerability of the patient.","sop":false},{"letter":"d","category":"Commitment","text":"Nursing care must follow the care plan tailored to each patient.","sop":true},{"letter":"e","category":"Commitment","text":"Nurses shall be given every facility and accessory they need to provide the best care.","sop":false},{"letter":"f","category":"Commitment","text":"Nurses shall have the authority to take decisions within their own area of practice, where that helps the patient.","sop":false}]},{"code":"COP.7","text":"Clinical Procedures & Procedural Safety","elements":[{"letter":"a","category":"Commitment","text":"Any intervention on a patient must be rational, weighed against whether the patient actually needs it.","sop":false},{"letter":"b","category":"Commitment","text":"Every procedure carried out on a patient shall follow written guidance.","sop":true},{"letter":"c","category":"Commitment","text":"The organisation must make sure that only a person qualified by law carries out a procedure on a patient.","sop":false},{"letter":"d","category":"CORE","text":"Special attention must be given to avoiding misidentification of the patient, the procedure or the site.","sop":true},{"letter":"e","category":"Commitment","text":"Before a procedure begins, the patient's side must be made aware of it, and it must proceed only with their documented approval.","sop":false},{"letter":"f","category":"Commitment","text":"Patients must be monitored before a procedure, during it, and after it.","sop":false},{"letter":"g","category":"Commitment","text":"Accurate documentation of the procedure must be present in the patient's file.","sop":false}]},{"code":"COP.8","text":"Blood & Transfusion Services","elements":[{"letter":"a","category":"Commitment","text":"Transfusion activities must lie within the limits the organisation has established for itself.","sop":false},{"letter":"b","category":"Commitment","text":"There shall be documented guidance for the collection, storage, testing and distribution of blood and blood components.","sop":true},{"letter":"c","category":"Commitment","text":"Safe storage practices must be followed from the time of collection to the time of infusion.","sop":false},{"letter":"d","category":"CORE","text":"The use of any blood or blood component must be justified for the patient it is used on.","sop":true},{"letter":"e","category":"Commitment","text":"There must be a defined time frame within which blood and blood components are made available, in routine and in emergency situations alike.","sop":true},{"letter":"f","category":"Achievement","text":"Once a transfusion is complete, the events related to it must be recorded, and any adverse happening noted, studied and understood so that it does not occur again.","sop":true},{"letter":"g","category":"Achievement","text":"The functioning of the blood centre shall be monitored by a quality assurance programme.","sop":true}]},{"code":"COP.9","text":"Intensive & Critical Care Units","elements":[{"letter":"a","category":"Commitment","text":"There must be documented guidance for giving sufficient care to patients who need intensive or high dependency care.","sop":true},{"letter":"b","category":"Commitment","text":"Well established admission and discharge criteria must be set and in place for intensive and high dependency care units.","sop":true},{"letter":"c","category":"Commitment","text":"Adequate people and adequate equipment must be available to support them.","sop":false},{"letter":"d","category":"Commitment","text":"There must be an established way of handling a shortage of beds, implemented and followed.","sop":true},{"letter":"e","category":"Commitment","text":"Measures to prevent infection and to handle it shall be implemented and followed.","sop":true},{"letter":"f","category":"Achievement","text":"There shall be a dedicated way of assuring the quality of the service given in intensive and high dependency areas.","sop":true},{"letter":"g","category":"Commitment","text":"Any counselling of the patient or the patient's family shall follow a defined mechanism.","sop":false}]},{"code":"COP.10","text":"Obstetric & Maternity Care","elements":[{"letter":"a","category":"Commitment","text":"Obstetric care shall be given in a safe and defined manner.","sop":true},{"letter":"b","category":"Commitment","text":"A high risk obstetric case must be identified and given the care it needs, and where required may be moved to another centre that suits it better.","sop":false},{"letter":"c","category":"Commitment","text":"Staff handling high risk obstetric cases shall be trained well enough to handle them.","sop":false},{"letter":"d","category":"Commitment","text":"An organisation providing obstetric care shall also provide antenatal services and care.","sop":true},{"letter":"e","category":"Achievement","text":"A birth companion shall be allowed during labour if the woman wishes it, and the organisation should encourage and welcome the practice.","sop":false},{"letter":"f","category":"Commitment","text":"Both the birth companion and the pregnant woman shall be treated with respect, and the woman's safety and confidentiality during labour must be ensured.","sop":false},{"letter":"g","category":"Commitment","text":"Any danger sign, and any other point worth noting, shall be communicated to the pregnant woman and to the birth companion by the consulting doctor.","sop":false},{"letter":"h","category":"Commitment","text":"Assessment of an obstetric patient must include maternal nutrition.","sop":false},{"letter":"i","category":"Commitment","text":"Perinatal monitoring and postnatal monitoring shall be implemented and followed, so that the care stays appropriate to the mother and the baby.","sop":false},{"letter":"j","category":"Commitment","text":"An organisation that accepts and treats a high risk obstetric case must also hold in mind that appropriate neonatal care can be given for it.","sop":false},{"letter":"k","category":"Commitment","text":"Assisted reproductive practices within the organisation shall be defined, and shall comply with the law.","sop":false}]},{"code":"COP.11","text":"Paediatric & Neonatal Care","elements":[{"letter":"a","category":"Commitment","text":"Paediatric services shall be given in a safe and defined manner.","sop":true},{"letter":"b","category":"Commitment","text":"Neonatal care shall align with the established official guidelines.","sop":true},{"letter":"c","category":"Commitment","text":"Anyone providing care to a paediatric patient must have experience appropriate to the age of the child.","sop":false},{"letter":"d","category":"Commitment","text":"The organisation shall make sure sufficient facilities are in place to give children the special care they need.","sop":false},{"letter":"e","category":"Commitment","text":"Assessment of a child must include the growth and development chart, the nutrition chart, and the immunisation record.","sop":false},{"letter":"f","category":"Commitment","text":"The organisation shall hold a documented action plan against a child or a neonate being abducted or abused, and for dealing with such a case.","sop":true},{"letter":"g","category":"Commitment","text":"The organisation shall educate on the diet plan, the immunisation plan, and parenting.","sop":false},{"letter":"h","category":"Excellence","text":"The organisation shall also make its healthcare services friendly to adolescent patients.","sop":false}]},{"code":"COP.12","text":"Procedural Sedation Controls","elements":[{"letter":"a","category":"Commitment","text":"Sedation must be provided uniformly, under documented guidance, and in compliance with accepted standards.","sop":true},{"letter":"b","category":"Commitment","text":"Documented consent to proceed with sedation must be obtained from the patient's side.","sop":false},{"letter":"c","category":"Commitment","text":"Sedation must be carried out only by people who are experienced and authorised by law.","sop":false},{"letter":"d","category":"Commitment","text":"The person giving the sedation must be assisted by a person monitoring it; the same person shall not do both.","sop":false},{"letter":"e","category":"Commitment","text":"Monitoring during sedation includes the heart rate, the rhythm of the heart, the blood pressure, the oxygen saturation, the amount of sedation given, and how much of it remains in the patient and what it is doing.","sop":false},{"letter":"f","category":"Commitment","text":"Monitoring during the procedure must be followed by monitoring after it, so that the patient is safe once the sedation is over, and every parameter monitored must be documented.","sop":false},{"letter":"g","category":"Commitment","text":"There must be criteria in place for moving a patient out of the recovery area, and a patient shall be moved only once those criteria are met.","sop":true},{"letter":"h","category":"Commitment","text":"Where a patient goes deeper into sedation than was expected, sufficient facilities, instruments and staff must be on hand to deal with it.","sop":false}]},{"code":"COP.13","text":"Anaesthesia Delivery & Monitoring","elements":[{"letter":"a","category":"Commitment","text":"Anaesthesia must be provided uniformly, under documented guidance, and in compliance with accepted standards.","sop":true},{"letter":"b","category":"CORE","text":"The assessment made before anaesthesia must be documented, and the care plan formulated from it.","sop":false},{"letter":"c","category":"Commitment","text":"A further assessment must be made before anaesthesia is induced.","sop":false},{"letter":"d","category":"Commitment","text":"Documented consent to proceed with anaesthesia must be obtained from the patient's side.","sop":false},{"letter":"e","category":"CORE","text":"Monitoring during anaesthesia includes the heart rate, the rhythm of the heart, the blood pressure, the oxygen saturation, the respiratory rate and the end tidal carbon dioxide.","sop":false},{"letter":"f","category":"Commitment","text":"Monitoring during the procedure must be followed by monitoring after it, so that the patient is safe once the anaesthesia is over, and every parameter monitored must be documented.","sop":false},{"letter":"g","category":"Commitment","text":"The anaesthesiologist must set the criteria for moving a patient out of the recovery area, and a patient shall be moved only once those criteria are met.","sop":true},{"letter":"h","category":"Commitment","text":"The medication used, and the type of anaesthesia chosen for the patient, must be recorded in the patient's record.","sop":false},{"letter":"i","category":"Commitment","text":"Procedures must be carried out with infection prevention in mind, so that one patient does not infect another.","sop":false},{"letter":"j","category":"Achievement","text":"Any adverse event related to the anaesthesia must be observed, analysed and documented in the patient's record.","sop":false}]},{"code":"COP.14","text":"Surgical Services & Peri-Operative Records","elements":[{"letter":"a","category":"Commitment","text":"Surgery must be provided uniformly, under documented guidance, and in compliance with accepted standards.","sop":true},{"letter":"b","category":"Commitment","text":"A patient about to undergo surgery must be assessed and a diagnosis reached beforehand, and the information they need must be given to them before the procedure.","sop":false},{"letter":"c","category":"Commitment","text":"Documented consent to proceed with the surgery must be obtained from the patient's side.","sop":false},{"letter":"d","category":"CORE","text":"Particular care must be taken against operating on the wrong site, on the wrong patient, or performing the wrong surgery.","sop":true},{"letter":"e","category":"Commitment","text":"Before the patient is moved, what took place during the operation must be documented in the patient's record.","sop":false},{"letter":"f","category":"Commitment","text":"There must be a documented plan guiding the care given to a patient after an operation.","sop":false},{"letter":"g","category":"Commitment","text":"Every operative activity and precaution must work towards preventing and controlling infection.","sop":false},{"letter":"h","category":"Commitment","text":"Inside the operating theatre, every facility and provision needed for a safe procedure must be available.","sop":false},{"letter":"i","category":"Achievement","text":"Operative services must be checked to have been delivered at the right quality.","sop":true},{"letter":"j","category":"Achievement","text":"Assuring that quality includes auditing the operating theatre and its environment.","sop":true}]},{"code":"COP.15","text":"Organ Transplant Governance","elements":[{"letter":"a","category":"CORE","text":"The organisation should make sure ethical and legal standards are maintained when it provides organ transplantation services.","sop":false},{"letter":"b","category":"Commitment","text":"The care given must be guided by approved guidelines.","sop":true},{"letter":"c","category":"Commitment","text":"Before the transplant, both the donor and the recipient must be trained, educated and counselled about the procedure.","sop":false},{"letter":"d","category":"CORE","text":"The organisation must take appropriate measures to make its patients, and the public, aware of organ donation.","sop":false}]},{"code":"COP.16","text":"Vulnerable Patient Safeguards","elements":[{"letter":"a","category":"CORE","text":"A patient who needs intensive monitoring and care must be identified and managed.","sop":true},{"letter":"b","category":"CORE","text":"A patient at risk of falling must be picked out, and cared for in the way that risk demands.","sop":true},{"letter":"c","category":"CORE","text":"Special care must be given to a patient at risk of pressure ulcers, or already suffering from them.","sop":true},{"letter":"d","category":"CORE","text":"A patient with deep vein thrombosis must be handled safely by the organisation.","sop":true},{"letter":"e","category":"Commitment","text":"An aggressive patient who may need restraint must be handled properly by the organisation.","sop":true}]},{"code":"COP.17","text":"Pain Assessment & Management","elements":[{"letter":"a","category":"Commitment","text":"The hospital must manage the patients who are suffering severe pain.","sop":true},{"letter":"b","category":"Commitment","text":"Pain management includes examining the patient for pain.","sop":false},{"letter":"c","category":"Commitment","text":"Assessment and reassessment must be carried out for a patient in pain.","sop":false},{"letter":"d","category":"Commitment","text":"The treatment plan must be adjusted to what that assessment finds and to how severe the pain is, so the care given stays optimal.","sop":false}]},{"code":"COP.18","text":"Rehabilitation & Therapy Services","elements":[{"letter":"a","category":"Commitment","text":"The type of rehabilitation the organisation provides must sit within the services it offers.","sop":false},{"letter":"b","category":"Commitment","text":"Rehabilitation must be provided properly and regularly.","sop":false},{"letter":"c","category":"Commitment","text":"The treatment plan must be formulated to include both medication management and rehabilitation, where rehabilitation is needed.","sop":false},{"letter":"d","category":"Commitment","text":"Sufficient provision must be made for delivering rehabilitation.","sop":false},{"letter":"e","category":"Commitment","text":"A patient must be assessed and reassessed, and their activity monitored, before and after rehabilitation.","sop":false},{"letter":"f","category":"Commitment","text":"Rehabilitation must be given with the risk of infection kept low, following the infection prevention precautions.","sop":false},{"letter":"g","category":"Excellence","text":"The plan for how the rehabilitation progresses must be designed, followed, and evaluated at regular intervals.","sop":false}]},{"code":"COP.19","text":"Nutritional Assessment & Therapeutic Diet","elements":[{"letter":"a","category":"Commitment","text":"Patients must be examined for their nutritional status.","sop":true},{"letter":"b","category":"Commitment","text":"Nutritional therapy must be modified according to what that examination finds.","sop":false},{"letter":"c","category":"Commitment","text":"The altered diet must be designed and implemented to meet the patient's needs.","sop":false},{"letter":"d","category":"Commitment","text":"Only the prescribed diet may reach the patient.","sop":false},{"letter":"e","category":"Commitment","text":"Where a patient is to receive food from the family, it must be made sure that what is brought falls within the patient's dietary boundaries.","sop":false}]},{"code":"COP.20","text":"End-of-Life & Palliative Care","elements":[{"letter":"a","category":"Commitment","text":"Care in the final stages of life must be provided appropriately.","sop":true},{"letter":"b","category":"Achievement","text":"Care in the last moments must be approached by a multidisciplinary team with experience in palliative care.","sop":false},{"letter":"c","category":"Commitment","text":"That approach must meet the legal requirements.","sop":false},{"letter":"d","category":"Commitment","text":"Any religious, cultural or other need expressed by the patient's side must be identified, respected and met by the organisation.","sop":false},{"letter":"e","category":"Commitment","text":"Symptomatic treatment, with pain management, must be assured.","sop":false}]}]},"MOM":{"code":"MOM","name":"Management of Medication","standards":[{"code":"MOM.1","text":"The pharmacy is well managed, and pharmacy products are handled safely throughout the organisation.","elements":[{"letter":"a","category":"Commitment","text":"There shall be a documented protocol for the hospital pharmacy's activities, to which it shall adhere completely.","sop":true},{"letter":"b","category":"Commitment","text":"Any activity involving medication inside the hospital shall be guided by a well-defined team that manages safe medication practice, both in the documentation and at the patient's side.","sop":false},{"letter":"c","category":"Achievement","text":"The guiding team shall update the functions of medication and its handling whenever necessary.","sop":false},{"letter":"d","category":"Commitment","text":"When the pharmacy is unavailable, there shall be a documented mechanism in place for arranging medication for patients.","sop":true},{"letter":"e","category":"Commitment","text":"The organisation shall take sole responsibility for making the information reach everywhere within it whenever there is a change in the pharmacy's functional activities, in medication stock, or where stock has run out.","sop":false}]},{"code":"MOM.2","text":"There shall be a master medication booklet in the organisation.","elements":[{"letter":"a","category":"CORE","text":"The medication master booklet shall be developed by the organisation and shall thereafter be maintained by the medication guiding team.","sop":false},{"letter":"b","category":"Commitment","text":"Medication may be added to or removed from the list where the team considers it necessary, supported by evidence. This revision shall take place at least once a year.","sop":false},{"letter":"c","category":"Commitment","text":"The finalised master drug list shall be made available to all clinicians within the organisation, for better medication safety and control.","sop":false},{"letter":"d","category":"Achievement","text":"Clinicians within the organisation shall prescribe medication contained in the master drug list.","sop":false},{"letter":"e","category":"Commitment","text":"For every medication held in the master drug list, there shall be a documented procurement protocol in place.","sop":true},{"letter":"f","category":"Commitment","text":"For medication not present in the formulary, there shall also be a documented protocol in place for its procurement.","sop":true}]},{"code":"MOM.3","text":"All medications are properly stocked and maintained, and are available at any time they are needed.","elements":[{"letter":"a","category":"CORE","text":"The pharmacy follows proper storage practice for each medication and ensures it complies with the storage instructions given by the manufacturer.","sop":false},{"letter":"b","category":"Commitment","text":"Storage uses standard stock arrangement methods, which help to prevent expired medicine remaining in the pharmacy.","sop":false},{"letter":"c","category":"CORE","text":"The organisation shall maintain a list of high-alert medications, revised when necessary with supporting evidence.","sop":true},{"letter":"d","category":"Achievement","text":"High-alert medications are also made available in the patient care areas outside the pharmacy that the organisation considers appropriate.","sop":false},{"letter":"e","category":"CORE","text":"Precautions such as separating two high-alert medications that look or sound alike are followed in every patient care area where those medications are stocked.","sop":true},{"letter":"f","category":"Commitment","text":"Life-saving and fast-acting medications needed at critical times are listed and stocked in the pharmacy and in the other critical care areas.","sop":true},{"letter":"g","category":"CORE","text":"The organisation shall ensure that life-saving and fast-acting medications needed at critical times are always available and never out of stock.","sop":false}]},{"code":"MOM.4","text":"Medication is handled responsibly and appropriately.","elements":[{"letter":"a","category":"Commitment","text":"The organisation shall ensure that suitable medication is prescribed whenever it is needed.","sop":true},{"letter":"b","category":"CORE","text":"A prescription shall carry the minimum parameters required for it to be valid.","sop":true},{"letter":"c","category":"Commitment","text":"Medication is prescribed taking the patient's medical history and drug allergy history into account.","sop":false},{"letter":"d","category":"Excellence","text":"To avoid prescribing errors, the organisation shall support its clinicians with suitable physical or electronic resources and guidance for choosing medication rationally.","sop":false},{"letter":"e","category":"CORE","text":"The patient's medication shall be reviewed at every ward shift and on admission, to help optimise the care plan.","sop":false},{"letter":"f","category":"CORE","text":"Oral orders shall be accepted only for medication on a defined list, and every oral order shall be followed by a written prescription within a defined time.","sop":true},{"letter":"g","category":"Achievement","text":"Every medication order is cross-verified, so that the patient is safe in respect of the medication given.","sop":false},{"letter":"h","category":"Achievement","text":"Where cross-verification finds a discrepancy, action shall be taken to stop it happening again.","sop":false}]},{"code":"MOM.5","text":"The same accepted pattern of medication ordering shall be followed in every clinical area where patients are cared for.","elements":[{"letter":"a","category":"Commitment","text":"Prescriptions are written only by medical practitioners, or by other personnel the organisation has authorised to write them.","sop":true},{"letter":"b","category":"Commitment","text":"Every medication order is recorded in a dedicated place in the patient's file, which also carries the parameters that identify the patient.","sop":false},{"letter":"c","category":"Commitment","text":"Every prescription must be understandable, must record when it was ordered, and must be authorised by the prescriber.","sop":false},{"letter":"d","category":"Commitment","text":"A prescription shall give, alongside the medication itself, the supporting detail that goes with it: the dose, the route, how often it is to be administered, and at what times.","sop":false}]},{"code":"MOM.6","text":"Prescriptions are attended to, and medication is dispensed following the safety precautions that prevent medication errors.","elements":[{"letter":"a","category":"Commitment","text":"Medication is dispensed in accordance with the documented and accepted safe dispensing parameters.","sop":true},{"letter":"b","category":"Commitment","text":"Medication can be recalled on a regulatory instruction, or where the integrity of the medication is in doubt, and a documented protocol for handling such a recall is in place.","sop":true},{"letter":"c","category":"Commitment","text":"Medication approaching its expiry is dealt with under a defined and authorised protocol.","sop":true},{"letter":"d","category":"CORE","text":"Medication leaving the pharmacy, for outpatients and inpatients alike, shall be labelled with what the pack contains: the name, the dose, the batch number and the expiry of the medication.","sop":true},{"letter":"e","category":"CORE","text":"High-alert medication is dispensed safely and only against a valid prescription, and every high-alert medication is reconfirmed for the correct strength, dose and formulation before it is dispensed.","sop":false},{"letter":"f","category":"Commitment","text":"Medication returned to the pharmacy, from inpatients and outpatients alike, shall follow a documented procedure.","sop":true}]},{"code":"MOM.7","text":"The administration of medication follows safety parameters and is done correctly.","elements":[{"letter":"a","category":"Commitment","text":"Only those individuals permitted and authorised by law may handle a patient's medication for administration.","sop":false},{"letter":"b","category":"Commitment","text":"The prepared medication is labelled before preparation of the next one begins.","sop":false},{"letter":"c","category":"Commitment","text":"The right patient is identified before administration.","sop":false},{"letter":"d","category":"CORE","text":"The medication in hand is cross-verified against the medication order sheet before it is administered to the patient.","sop":false},{"letter":"e","category":"Commitment","text":"The strength of the medication is double-checked against the medication chart before administration.","sop":false},{"letter":"f","category":"Commitment","text":"The route the preparation is intended for is confirmed before administration.","sop":false},{"letter":"g","category":"Commitment","text":"Medication is administered at the right times and at the right intervals.","sop":false},{"letter":"h","category":"CORE","text":"Precautionary measures are taken to confirm that catheters and patient tubes are properly connected.","sop":true},{"letter":"i","category":"Commitment","text":"Every administration of medication shall be documented in that patient's file.","sop":false},{"letter":"j","category":"Commitment","text":"The organisation shall frame a policy on the self-administration of medication, as a documented protocol.","sop":true},{"letter":"k","category":"Commitment","text":"Medication brought from home, or from outside the hospital, is regulated under the organisation's documented policy.","sop":true}]},{"code":"MOM.8","text":"The administration of medication is followed by observing its effects.","elements":[{"letter":"a","category":"Commitment","text":"Every patient under the organisation's care shall be observed for the effects of medication once it has been administered.","sop":true},{"letter":"b","category":"Commitment","text":"Based on the effects observed, the medication parameters may be altered where that is considered necessary.","sop":false},{"letter":"c","category":"CORE","text":"Any unwanted effect of a medication shall be identified and noted, and a guiding document shall be in place to support that process.","sop":true},{"letter":"d","category":"Commitment","text":"Adverse medication reactions that have been identified shall be notified to the respective regulatory bodies within a specified time.","sop":true},{"letter":"e","category":"Commitment","text":"A root cause analysis is carried out for every medication-related adverse effect, including an error and a near miss.","sop":false},{"letter":"f","category":"Commitment","text":"Action is taken to prevent these medication-associated unwanted events happening again.","sop":false}]},{"code":"MOM.9","text":"Narcotic, chemotherapy, radiopharmaceutical and psychotropic substances are handled safely, and with proper protection for those handling them.","elements":[{"letter":"a","category":"Commitment","text":"Controlled substances — narcotic and psychotropic medication, and chemotherapy and radiopharmaceutical agents — are handled appropriately, under documented process guidance.","sop":true},{"letter":"b","category":"Commitment","text":"Controlled substances — narcotic and psychotropic medication, and chemotherapy and radiopharmaceutical agents — are handled only by those who are legally authorised to do so.","sop":false},{"letter":"c","category":"Commitment","text":"Controlled substances — narcotic and psychotropic medication, and chemotherapy and radiopharmaceutical agents — are stored separately from ordinary medication, and kept protected.","sop":false},{"letter":"d","category":"Commitment","text":"Controlled substances — narcotic and psychotropic medication, and chemotherapy and radiopharmaceutical agents — are handled, diluted where that is needed, and administered only by individuals who are legally authorised to do so.","sop":false},{"letter":"e","category":"Commitment","text":"Every activity involving controlled substances — narcotic and psychotropic medication, and chemotherapy and radiopharmaceutical agents — shall leave documented proof of its use.","sop":false}]},{"code":"MOM.10","text":"The organisation uses implants, prostheses and medical devices under defined guidance.","elements":[{"letter":"a","category":"Commitment","text":"Medical devices shall be used under the guidelines the manufacturer provides, or under the applicable scientific guidance.","sop":false},{"letter":"b","category":"Commitment","text":"There shall be regulatory governance over the use of medical devices and implants.","sop":true},{"letter":"c","category":"Commitment","text":"The organisation must have a practice of guiding the patient, and the patient's attender, through the implant or prosthesis process, explaining the advantages and disadvantages of the procedure and of what follows it.","sop":false},{"letter":"d","category":"Commitment","text":"The details of a medical device used for a patient must be made available in defined places: the medication chart, the patient's discharge documents, and the organisation's device register.","sop":false},{"letter":"e","category":"Achievement","text":"Where a device is found to be spurious, or where a regulatory body so instructs, devices already in use can be withdrawn under documented guidance.","sop":true}]},{"code":"MOM.11","text":"Consumables and medical supplies shall be under documented guidance, and are always available.","elements":[{"letter":"a","category":"Commitment","text":"The organisation shall have a process in place to procure and handle supplies and consumables.","sop":true},{"letter":"b","category":"Commitment","text":"All supplies and consumables are handled appropriately.","sop":false},{"letter":"c","category":"Commitment","text":"All supplies and consumables are stored in a safe location, where the temperature and humidity meet what the manufacturer requires.","sop":false},{"letter":"d","category":"Commitment","text":"A uniform stocking practice shall be applied to consumables.","sop":false},{"letter":"e","category":"Commitment","text":"The appropriateness of the medical supplies and consumables is checked and documented.","sop":false}]}]},"PRE":{"code":"PRE","name":"Patient Rights and Education","standards":[{"code":"PRE.1","text":"Patient rights and responsibilities are protected, respected and communicated to the patient and their family","elements":[{"letter":"a","category":"Commitment","text":"The rights and responsibilities of patients under the organisation are displayed and documented.","sop":true},{"letter":"b","category":"Achievement","text":"All patient and family rights and responsibilities are respected and acknowledged.","sop":true},{"letter":"c","category":"CORE","text":"The rights and responsibilities are safeguarded.","sop":false},{"letter":"d","category":"CORE","text":"If the rights are violated, the organisation has a way to report them.","sop":false},{"letter":"e","category":"CORE","text":"All violations are tracked, analysed and necessary actions are taken to prevent them in future.","sop":false}]},{"code":"PRE.2","text":"Patient rights must support their values and beliefs, and in making any decision, the patient and family members are involved","elements":[{"letter":"a","category":"Commitment","text":"All values, beliefs and any specific requests for spiritual needs of the patient and family are to be responded to and supported.","sop":false},{"letter":"b","category":"Commitment","text":"The privacy of the patient is protected during any medical procedure.","sop":false},{"letter":"c","category":"Commitment","text":"Patient rights must also include safeguarding from abuse or neglect.","sop":false},{"letter":"d","category":"CORE","text":"Confidentiality of patient information is maintained.","sop":false},{"letter":"e","category":"Commitment","text":"Refusal of treatment is respected.","sop":false},{"letter":"f","category":"Commitment","text":"Opting for a second opinion is respected.","sop":false},{"letter":"g","category":"CORE","text":"Any medical procedure on the patient is explained beforehand, and a written consent is obtained and documented from the patient or family.","sop":false},{"letter":"h","category":"Commitment","text":"Patients and their family must know that they have the right to complain, and know the procedure on how to do so.","sop":false},{"letter":"i","category":"Commitment","text":"Financial counselling of the treatment must be provided.","sop":false},{"letter":"j","category":"Commitment","text":"Upon request and approval, the patient or family can have access to the patient's clinical records.","sop":false},{"letter":"k","category":"Commitment","text":"Information on the consultant, treatment plan, treatment progress and other requirements is to be disclosed to the patient's family if requested.","sop":false},{"letter":"l","category":"Achievement","text":"Patient rights allow the patient to decide which information is to be disclosed to them and their family.","sop":false}]},{"code":"PRE.3","text":"The organisation makes sure the patient and family members are informed of all the clinical parameters of the patient, and decisions are made collaboratively with them","elements":[{"letter":"a","category":"CORE","text":"The patient side is informed of the clinical status of the patient at every stage of treatment, i.e. the condition, possible outcome, proposed care plan, etc.","sop":false},{"letter":"b","category":"Achievement","text":"The treatment plan is designed and changed upon proper communication with the patient side.","sop":false},{"letter":"c","category":"Commitment","text":"Any test results or findings are communicated with the patient side.","sop":false},{"letter":"d","category":"Commitment","text":"The patient's clinical status is updated to the patient side at proper time intervals.","sop":false},{"letter":"e","category":"Achievement","text":"Patient counselling is provided whenever appropriate and necessary.","sop":false}]},{"code":"PRE.4","text":"The informed consent process is implemented","elements":[{"letter":"a","category":"CORE","text":"Whenever required, informed consent is obtained by the organisation.","sop":true},{"letter":"b","category":"Commitment","text":"The informed consent adheres to accepted standards.","sop":false},{"letter":"c","category":"CORE","text":"Informed consent must cover all aspects of the patient's clinical parameters, such as risks, benefits, who their doctor is, etc.","sop":false},{"letter":"d","category":"Commitment","text":"The organisation has an established format for declaring who is eligible to provide informed consent when the patient is not able to provide it.","sop":true},{"letter":"e","category":"CORE","text":"The person who performs the clinical procedure has to obtain the informed consent from the patient or family.","sop":false}]},{"code":"PRE.5","text":"The patient and family members must be educated and informed about their healthcare requirements","elements":[{"letter":"a","category":"CORE","text":"Any information communicated with the patient must be communicated in their own comfortable language if requested.","sop":false},{"letter":"b","category":"Commitment","text":"The patient and family members are counselled about safe medication usage.","sop":false},{"letter":"c","category":"Commitment","text":"Counselling includes education about taking foods that do not interact with the patient's medication.","sop":false},{"letter":"d","category":"Commitment","text":"Information about diet and nutritional health is also counselled.","sop":false},{"letter":"e","category":"Commitment","text":"Immunisation counselling is also provided.","sop":false},{"letter":"f","category":"Commitment","text":"Counselling on pain management is provided if needed.","sop":false},{"letter":"g","category":"Commitment","text":"Counselling is provided on the current diagnosis of the patient and its prevention strategies in future.","sop":false},{"letter":"h","category":"Commitment","text":"Counselling is provided on the prevention of healthcare-acquired infections.","sop":false},{"letter":"i","category":"Achievement","text":"The patient's special requirements are addressed.","sop":false},{"letter":"j","category":"Excellence","text":"The organisation engages patients to support their clinical improvement.","sop":false}]},{"code":"PRE.6","text":"The estimated cost of treatment is communicated to the patient","elements":[{"letter":"a","category":"CORE","text":"The pricing policy of all services is displayed in all areas.","sop":false},{"letter":"b","category":"Commitment","text":"Patients are provided with their tariff lists.","sop":false},{"letter":"c","category":"Commitment","text":"Financial counselling is provided.","sop":false},{"letter":"d","category":"Commitment","text":"Financial counselling involves explaining the situations where the estimated cost may differ based on any care plan alteration.","sop":false}]},{"code":"PRE.7","text":"The organisation captures the patients' responses and reviews to understand the complaints and then correct them","elements":[{"letter":"a","category":"Commitment","text":"The organisation captures the patients' review of the service provided and their satisfaction.","sop":false},{"letter":"b","category":"Achievement","text":"Patient experience is captured.","sop":false},{"letter":"c","category":"CORE","text":"The organisation has a documented way of addressing complaints.","sop":true},{"letter":"d","category":"Commitment","text":"Patients are made aware of the procedure for providing a review.","sop":false},{"letter":"e","category":"Commitment","text":"Obtained feedback is reviewed and addressed within a defined period.","sop":false},{"letter":"f","category":"Commitment","text":"CAPA is done based on the findings.","sop":false}]},{"code":"PRE.8","text":"The organisation communicates with the patient in a standard manner","elements":[{"letter":"a","category":"Commitment","text":"There is effective communication between the patient and the organisation.","sop":true},{"letter":"b","category":"Commitment","text":"Specific situations which need more communication with the patient are identified.","sop":true},{"letter":"c","category":"Commitment","text":"The extra communication is also done appropriately.","sop":true},{"letter":"d","category":"Commitment","text":"The organisation makes sure they do not declare any communication unacceptable.","sop":false},{"letter":"e","category":"Achievement","text":"The organisation tracks and analyses the communication that they deem to be appropriate.","sop":false}]}]},"IPC":{"code":"IPC","name":"Infection Prevention and Control","standards":[{"code":"IPC.1","text":"Institutional Surveillance and Programme Management Framework","elements":[{"letter":"a","category":"CORE","text":"Systemic Safety Architecture: A dedicated web-based repository hosting version-controlled administrative master plans and infection control policies with mandatory orientation logs.","sop":true},{"letter":"b","category":"Commitment","text":"Targeted Risk Isolation Mapping: Dedicated inventory and risk evaluation modules isolating cross-contamination vulnerabilities across operational departments.","sop":true},{"letter":"c","category":"Commitment","text":"The documented process of the infection control movement shall be revised and altered with supporting evidence at least once a year.","sop":false},{"letter":"d","category":"Achievement","text":"There shall be a measurable way to assess the actions of the infection control process.","sop":false},{"letter":"e","category":"Commitment","text":"There shall be a panel of members in the organisation taking care of the actions of the infection control movement. A documented operating procedure shall be made available.","sop":true},{"letter":"f","category":"Commitment","text":"The organisation shall also have a team of primary members taking care of the infection control activities, who then report their actions and findings to the panel.","sop":true},{"letter":"g","category":"Commitment","text":"The team shall be guided by a person appointed by the organisation with documented responsibilities, who leads the activities of the team and guides its members.","sop":true},{"letter":"h","category":"Commitment","text":"There shall be a member from the nursing department also as a primary member in the infection control team.","sop":true},{"letter":"i","category":"Commitment","text":"The organisation organises initiatives and educational activities for the community.","sop":false},{"letter":"j","category":"Commitment","text":"The organisation shall participate actively in times of infectious outbreaks in the community.","sop":false}]},{"code":"IPC.2","text":"Infrastructure Isolation and Resource Allocation Matrix","elements":[{"letter":"a","category":"CORE","text":"Separate funds from the annual budget must be allocated towards infection control activities.","sop":false},{"letter":"b","category":"Commitment","text":"The organisation must make sure all self-protective products related to infection are made available in adequate quantities.","sop":false},{"letter":"c","category":"CORE","text":"Bedside Sanitization Access Map: Spatial verification logs mapping and auditing fully accessible hand-hygiene assets across all clinical touchpoints.","sop":false},{"letter":"d","category":"Commitment","text":"Modern transmission-based precautions and separate nursing facilities for taking care of such patients are made available in the organisation.","sop":false}]},{"code":"IPC.3","text":"Clinical Area Precautions and Stewardship Protocols","elements":[{"letter":"a","category":"CORE","text":"Primary precautionary measures by the organisation to avoid infections must be designed, implemented and followed by the organisation.","sop":true},{"letter":"b","category":"CORE","text":"The organisation must stick with laid down proper hand washing practices.","sop":true},{"letter":"c","category":"Commitment","text":"The organisation must stick with laid down transmission based infection precautionary practices.","sop":true},{"letter":"d","category":"CORE","text":"Injection and infusion practices must be handled in a safe manner.","sop":true},{"letter":"e","category":"Commitment","text":"A documented policy for antimicrobials handling and usage must be present and made available by the organisation.","sop":true},{"letter":"f","category":"CORE","text":"The organisation has a separate team to monitor and carry out safe and rational antimicrobials use.","sop":false}]},{"code":"IPC.4","text":"Operational Support Service Sanitation Controls","elements":[{"letter":"a","category":"Commitment","text":"Infection prevention must also cover infrastructure and engineering works in the organisation.","sop":true},{"letter":"b","category":"Commitment","text":"Consideration must be given to prevent any infectious risk during construction and renovation.","sop":true},{"letter":"c","category":"CORE","text":"The organisation must make sure that the housekeeping department follows documented infection control practices.","sop":true},{"letter":"d","category":"CORE","text":"Safe and secure biomedical waste management shall be in place.","sop":false},{"letter":"e","category":"Commitment","text":"The organisation must make sure of the implementation and application of safe linen and laundry management procedures.","sop":true},{"letter":"f","category":"Commitment","text":"The organisation must also make sure of kitchen cleanliness, and address any problem with food and food handling.","sop":true}]},{"code":"IPC.5","text":"Healthcare-Associated Infection (HAI) Target Surveillance Matrix","elements":[{"letter":"a","category":"Commitment","text":"The organisation must have preventive measures in place to avoid urinary tract infections arising from indwelling catheters.","sop":false},{"letter":"b","category":"Commitment","text":"Ventilator associated events must be addressed, and the measures that prevent them designed, documented and implemented.","sop":false},{"letter":"c","category":"Commitment","text":"Preventive measures to avoid bloodstream infections linked to central lines must be implemented.","sop":false},{"letter":"d","category":"Commitment","text":"The organisation must have the necessary preventive actions in place to avoid surgical site infections.","sop":false}]},{"code":"IPC.6","text":"Epidemiological Surveillance Analytics and Trend Engine","elements":[{"letter":"a","category":"CORE","text":"The monitoring must include identifying and calculating the infection risk, the infection rate, and the trend over time.","sop":false},{"letter":"b","category":"Commitment","text":"The data obtained through monitoring must be cross checked and addressed by the infection prevention and control team.","sop":false},{"letter":"c","category":"Commitment","text":"Once the high risk areas and high risk functions are identified, continuous monitoring must be carried out over them.","sop":false},{"letter":"d","category":"CORE","text":"The monitoring must also cover adherence to the laid down hand washing and hand hygiene practices.","sop":false},{"letter":"e","category":"Achievement","text":"Monitoring must also cover the identification and handling of organisms that are resistant to multiple antimicrobials.","sop":false},{"letter":"f","category":"CORE","text":"Monitoring of housekeeping practices must also form a part of infection monitoring.","sop":false},{"letter":"g","category":"Commitment","text":"All the observed information on infection control must be reported to the respective healthcare professionals.","sop":false},{"letter":"h","category":"Commitment","text":"Outbreaks of infection, if any, must be identified, and preventive actions to avoid them in future must be undertaken.","sop":true},{"letter":"i","category":"Commitment","text":"All the observed and reported data concerning infections must be addressed, with corrective action for what has been found and preventive action to stop it recurring.","sop":false}]},{"code":"IPC.7","text":"CSSD Processing Controls and Device Sterilization Steps","elements":[{"letter":"a","category":"Commitment","text":"The organisation should make sure that a dedicated sterilization area with appropriate zoning is made available.","sop":false},{"letter":"b","category":"CORE","text":"A documented protocol must be present explaining the sterilization, cleaning and disinfection practices, and how items are taken to and issued from the sterilization area.","sop":true},{"letter":"c","category":"Commitment","text":"A documented protocol must be in place for which items may be reused, and how they are reused after proper sterilization.","sop":true},{"letter":"d","category":"Commitment","text":"The sterilization process, and the calibration of the instruments that carry it out, must be checked regularly against written guidance, and the reports maintained.","sop":true},{"letter":"e","category":"Commitment","text":"When a breakdown or any other problem with the sterilizing system is identified, there shall be a documented recall procedure to collect back the items already distributed across the organisation.","sop":true}]},{"code":"IPC.8","text":"Occupational Health Safety Gates and Staff Exposure Records","elements":[{"letter":"a","category":"Commitment","text":"The organisation must apply work safety practices against infection — against its staff being infected, and against infection spreading among other healthcare professionals.","sop":true},{"letter":"b","category":"Commitment","text":"There must be an immunization policy in place for the staff working in the organisation.","sop":true},{"letter":"c","category":"Achievement","text":"For those at high risk of transmitting infection, the work plan shall be restricted to avoid the spread of transmissible infections.","sop":false},{"letter":"d","category":"Commitment","text":"The organisation must have a preventive action plan against exposure to blood and body fluids.","sop":false},{"letter":"e","category":"Commitment","text":"Besides the pre-exposure preventive measures, the organisation must also have a post-exposure action plan, as per accepted protocol, for every staff member who needs one.","sop":true}]}]},"PSQ":{"code":"PSQ","name":"Patient Safety and Quality Improvement","standards":[{"code":"PSQ.1","text":"Patient Safety Programme Governance","elements":[{"letter":"a","category":"CORE","text":"A patient safety committee must be formed. It identifies the risks to patient safety, reviews incidents, puts corrective and preventive actions in place, watches the patient safety indicators, and works continuously to make the hospital safer.","sop":true},{"letter":"b","category":"Commitment","text":"The patient safety programme must cover every major area: identifying the patient, medication safety, preventing infection, falls, safe surgery, transfusion, managing incidents, emergency preparedness, communication, and the rights of the patient.","sop":false},{"letter":"c","category":"Commitment","text":"No-harm events, near misses, adverse events and sentinel events must all be watched and documented clearly.","sop":false},{"letter":"d","category":"Commitment","text":"A designated patient safety officer must oversee the patient safety programmes, and report the safety activities and their outcomes to top management.","sop":false},{"letter":"e","category":"Commitment","text":"The analysis must be done with tools such as FMEA and HIRA, and the improvements must follow from what that analysis shows.","sop":false},{"letter":"f","category":"Commitment","text":"The safety programme shall be reviewed and updated every year.","sop":false},{"letter":"g","category":"CORE","text":"The organisation should follow and put into practice the national and the international safety goals.","sop":false}]},{"code":"PSQ.2","text":"Quality Improvement Programme Structure","elements":[{"letter":"a","category":"CORE","text":"A quality improvement committee must be formed.","sop":true},{"letter":"b","category":"Commitment","text":"The quality manual, the mock drill calendar and the committee calendar must be available and kept up to date.","sop":true},{"letter":"c","category":"Excellence","text":"The efficiency and the effectiveness of the safety and quality processes must be improved using quality tools, and that work must be documented.","sop":false},{"letter":"d","category":"Excellence","text":"Improvement must be continuous, and aimed at better clinical care.","sop":false},{"letter":"e","category":"Commitment","text":"There must be a person — an accreditation coordinator or a quality representative — who trains the organisation in the accreditation standards and puts them into practice across it.","sop":true},{"letter":"f","category":"Commitment","text":"Every audit finding, and every performance improvement activity, shall be discussed in the committee.","sop":true},{"letter":"g","category":"Commitment","text":"The quality manual must be updated once a year.","sop":false},{"letter":"h","category":"Commitment","text":"An internal audit must be carried out by the team once every six months, and documented.","sop":true},{"letter":"i","category":"CORE","text":"Nursing audits shall be carried out to judge and assure the competence of the staff in the duties they are given, so that nursing care improves.","sop":true}]},{"code":"PSQ.3","text":"Quality Indicator Monitoring","elements":[{"letter":"a","category":"Commitment","text":"The indicators given by NABH must be followed.","sop":false},{"letter":"b","category":"CORE","text":"Indicators covering the hospital acquired infection bundles must be watched, so that CAUTI, CLABSI, SSI and VAP are prevented.","sop":false},{"letter":"c","category":"Commitment","text":"Indicators such as how long a patient waits for consultation and for investigation, and how far equipment and the operating theatre are used, must be captured and watched.","sop":false},{"letter":"d","category":"CORE","text":"Indicators covering patient safety must be watched, so that it improves.","sop":false},{"letter":"e","category":"Commitment","text":"The quality team must validate the indicator data that has been captured.","sop":false},{"letter":"f","category":"Commitment","text":"The indicators captured shall be analysed, and the appropriate corrective and preventive action put in place on what is found.","sop":false},{"letter":"g","category":"Commitment","text":"Quality improvement must be carried out in the organisation on the strength of that analysis.","sop":false},{"letter":"h","category":"Achievement","text":"Feedback must be gathered, so that every service improves.","sop":false}]},{"code":"PSQ.4","text":"Improvement Projects & Outcome Measures","elements":[{"letter":"a","category":"CORE","text":"At least two quality improvement projects must be carried out in a year.","sop":false},{"letter":"b","category":"Achievement","text":"Those projects should be aimed mainly at efficiency and at cost effectiveness.","sop":false},{"letter":"c","category":"Commitment","text":"The improvement work must be carried out using quality tools.","sop":false},{"letter":"d","category":"Achievement","text":"The organisation should have a format for capturing the outcome measures the patient reports.","sop":false}]},{"code":"PSQ.5","text":"Clinical Audit Cycle","elements":[{"letter":"a","category":"Commitment","text":"A clinical audit must be carried out, so that the quality of care improves.","sop":false},{"letter":"b","category":"Commitment","text":"The organisation should define which parameters are to be audited.","sop":false},{"letter":"c","category":"Achievement","text":"Nurses and doctors are members of the clinical audit, and a committee must be framed for it.","sop":false},{"letter":"d","category":"Commitment","text":"The privacy and the confidentiality of patients and of staff must be protected.","sop":false},{"letter":"e","category":"Commitment","text":"The audit checklist, and what the audit found, must be documented.","sop":false},{"letter":"f","category":"Commitment","text":"What the audit found must be analysed, and the remedial measures taken.","sop":false}]},{"code":"PSQ.6","text":"Safety Culture & Leadership Commitment","elements":[{"letter":"a","category":"Achievement","text":"The hospital should identify and watch the quality and patient safety indicators that matter, to see whether the care it gives and the services it runs are safe and effective.","sop":false},{"letter":"b","category":"Commitment","text":"The hospital should analyse that quality data, find the problems and the gaps in it, and act to correct and improve them.","sop":false},{"letter":"c","category":"Commitment","text":"The organisation should act on what the quality data shows, and then check whether the action has improved the situation.","sop":false},{"letter":"d","category":"Commitment","text":"The organisation should tell the people concerned what the quality results were and what improvement action followed.","sop":false},{"letter":"e","category":"Achievement","text":"Once improvement action has been taken, the hospital should check whether the problem has actually reduced, and whether the improvement is holding.","sop":false},{"letter":"f","category":"Excellence","text":"The organisation should keep looking for ways to improve quality and patient safety, on the strength of the results it gets.","sop":false}]},{"code":"PSQ.7","text":"Incident Reporting & Root Cause Analysis","elements":[{"letter":"a","category":"CORE","text":"There must be a proper system for reporting patient safety incidents and near misses.","sop":true},{"letter":"b","category":"Commitment","text":"The organisation should review the incidents reported, find the reasons behind them, and identify what needs to improve.","sop":true},{"letter":"c","category":"Commitment","text":"The hospital should act to correct the problem, and to stop it happening again.","sop":false},{"letter":"d","category":"Commitment","text":"The hospital should learn from its incidents and share those lessons with the staff, so that the same problem does not return.","sop":false},{"letter":"e","category":"Achievement","text":"The organisation should check whether the action worked, and whether the same incident is still occurring.","sop":false},{"letter":"f","category":"Commitment","text":"The hospital should use what its incidents and its lessons have taught it to make the whole patient safety system better.","sop":false}]}]},"ROM":{"code":"ROM","name":"Responsibility of Management","standards":[{"code":"ROM.1","text":"Governance Roles and Responsibilities","elements":[{"letter":"a","category":"CORE","text":"The members responsible for governance must be identified, and their duties and responsibilities assigned to them.","sop":true},{"letter":"b","category":"Commitment","text":"Those members must put forward the organisation's vision, its mission and its values.","sop":true},{"letter":"c","category":"Commitment","text":"They must deal with the strategic and operational plans, and may approve the annual budget.","sop":true},{"letter":"d","category":"Commitment","text":"They must examine how the organisation is performing, and whether it still sits with its mission.","sop":false},{"letter":"e","category":"Commitment","text":"They may appoint further experienced members beneath them to support their roles and responsibilities.","sop":false},{"letter":"f","category":"Commitment","text":"They must handle and manage the structure through which governance, quality improvement and safety are put into practice.","sop":true},{"letter":"g","category":"Commitment","text":"They must prepare the governance structure and the way it is to work.","sop":false},{"letter":"h","category":"Achievement","text":"They shall also deal with the legal and the ethical aspects of the organisation.","sop":false},{"letter":"i","category":"Commitment","text":"The governance members must tell the public how the organisation performs against its standards, and where its quality stands.","sop":false}]},{"code":"ROM.2","text":"Ethical Institutional Management","elements":[{"letter":"a","category":"CORE","text":"The leadership must develop and maintain the ethical framework of the organisation.","sop":true},{"letter":"b","category":"Commitment","text":"Developing that framework includes deciding how ethical issues and difficulties are to be dealt with.","sop":true},{"letter":"c","category":"Commitment","text":"The ownership of the organisation must be declared.","sop":false},{"letter":"d","category":"Commitment","text":"Accreditations and affiliations must be displayed to the public.","sop":false}]},{"code":"ROM.3","text":"ESG and Long-Term System Sustainability","elements":[{"letter":"a","category":"Commitment","text":"Environmental, social and governance responsibilities must be addressed and put forward by the organisation.","sop":false},{"letter":"b","category":"Commitment","text":"The hospital must make an effort to adopt an eco-friendly and energy saving plan.","sop":true},{"letter":"c","category":"Commitment","text":"The social responsibility of the organisation must be laid out.","sop":false},{"letter":"d","category":"Commitment","text":"The organisation must take care of its own people.","sop":false},{"letter":"e","category":"Excellence","text":"The organisation must follow eco-friendly sourcing practices.","sop":false},{"letter":"f","category":"Achievement","text":"The organisation shall contribute to preventing pollution and to promoting eco-friendly practice, by encouraging its employees and staff to share common transport in support of a green strategy.","sop":false},{"letter":"g","category":"Achievement","text":"The organisation must ensure it is financially stable and sustainable, without that costing the quality of the healthcare it delivers.","sop":false}]},{"code":"ROM.4","text":"Executive Leadership and Day-to-Day Operations","elements":[{"letter":"a","category":"Commitment","text":"The person leading the organisation shall have sufficient experience in the field.","sop":false},{"letter":"b","category":"CORE","text":"That person must abide by the legislative and the regulatory requirements.","sop":false},{"letter":"c","category":"Commitment","text":"The leader shall appoint departmental heads to help run the organisation day to day.","sop":false},{"letter":"d","category":"Achievement","text":"The organisation must see that its departments show effective leadership.","sop":false},{"letter":"e","category":"Achievement","text":"The effectiveness of the organisation's leader must be reviewed.","sop":false}]},{"code":"ROM.5","text":"Professionalism and Operational Optimization","elements":[{"letter":"a","category":"Commitment","text":"The organisation must plan its future and develop achievable long term and short term goals, with the input of its stakeholders and its board.","sop":false},{"letter":"b","category":"Commitment","text":"To reach those goals and objectives, the organisation must see that it is functioning properly, checked internally and by outside agencies, and any discrepancy found must be resolved.","sop":true},{"letter":"c","category":"Commitment","text":"The budget for operations must be worked out and set down every year.","sop":false},{"letter":"d","category":"Achievement","text":"The performance of the committees must be reviewed, for how efficient and how appropriate they are.","sop":false},{"letter":"e","category":"Commitment","text":"The organisation must hold documented, achievable targets, and monitor its progress towards them.","sop":true},{"letter":"f","category":"Excellence","text":"The hospital must develop, and adapt to, changes in the way it works or the way it is structured.","sop":true}]},{"code":"ROM.6","text":"Risk Management Integration","elements":[{"letter":"a","category":"CORE","text":"The organisation must see that risk management measures are in place and documented.","sop":true},{"letter":"b","category":"Commitment","text":"Funding for handling risk shall be provided by the organisation.","sop":false},{"letter":"c","category":"Commitment","text":"The leadership must see that quality improvement, risk management and the strategic measures work together.","sop":false},{"letter":"d","category":"Achievement","text":"The organisation must see that system failures are reported promptly, internally and externally.","sop":true},{"letter":"e","category":"Commitment","text":"Every service provided through an outside party must be covered by a documented agreement.","sop":false},{"letter":"f","category":"Achievement","text":"The organisation must see that an outsourced service does not cost it quality or improvement.","sop":false}]}]},"FMS":{"code":"FMS","name":"Facility Management and Safety","standards":[{"code":"FMS.1","text":"The organisation must make sure all patients are safe within their environment","elements":[{"letter":"a","category":"CORE","text":"Devices that ensure patient safety are made available throughout the organisation.","sop":false},{"letter":"b","category":"Commitment","text":"Measures are taken to assist the differently-abled population too.","sop":false},{"letter":"c","category":"CORE","text":"Monthly facility audit rounds are conducted.","sop":false},{"letter":"d","category":"Commitment","text":"Identified parameters are documented, and CAPA is done for them.","sop":false},{"letter":"e","category":"Commitment","text":"Risk assessment is done before any construction or destruction that may happen within the hospital.","sop":false}]},{"code":"FMS.2","text":"Facilities in the organisation must function as per said protocols in a way that promotes environment friendliness","elements":[{"letter":"a","category":"Commitment","text":"Space and facilities are made adequate to meet the goals and values of the organisation.","sop":false},{"letter":"b","category":"Commitment","text":"Updated maps, blueprints and drawings of the respective facilities are made available.","sop":false},{"letter":"c","category":"CORE","text":"Signages are made available both inside and outside the organisation for better understanding.","sop":false},{"letter":"d","category":"CORE","text":"The organisation makes sure there is no power or water shortage within its premises.","sop":false},{"letter":"e","category":"Commitment","text":"Alternate backup arrangements are made in case of any failure in the system.","sop":false},{"letter":"f","category":"Commitment","text":"The functioning of the current and backup arrangements is audited at predetermined intervals.","sop":false}]},{"code":"FMS.3","text":"The organisation and its facilities must work in a way that ensures the safety of the patient side","elements":[{"letter":"a","category":"Commitment","text":"Areas that need additional security and accessibility parameters are laid down by operational planning.","sop":true},{"letter":"b","category":"Excellence","text":"Whenever construction of new or renovation of existing buildings or equipment is carried out, the organisation ensures patient safety, especially in the areas where critical patients are admitted.","sop":false},{"letter":"c","category":"Commitment","text":"Power safety is ensured through regular audits.","sop":false},{"letter":"d","category":"Commitment","text":"Unused and unwanted materials are condemned by the organisation.","sop":true},{"letter":"e","category":"CORE","text":"Highly inflammable and hazardous material safety is ensured by the organisation.","sop":true},{"letter":"f","category":"Commitment","text":"Spill management is in place through a documented protocol.","sop":true}]},{"code":"FMS.4","text":"The organisation must have facility, engineering support and utility systems in place","elements":[{"letter":"a","category":"Commitment","text":"The organisation must also have plans for the utility and engineering equipment to meet the organisation's goals and values.","sop":false},{"letter":"b","category":"Commitment","text":"Documented equipment control is available.","sop":false},{"letter":"c","category":"CORE","text":"There must be a documented preventive maintenance plan in place.","sop":true},{"letter":"d","category":"Commitment","text":"Examination and calibration of equipment are done at regular intervals.","sop":false},{"letter":"e","category":"Commitment","text":"Only department-specific competent staff must handle the utility and facility operations.","sop":false},{"letter":"f","category":"Commitment","text":"The staff allotted are contactable 24/7.","sop":false},{"letter":"g","category":"Achievement","text":"Critical equipment downtime is documented, and CAPA is done for the same and submitted.","sop":false},{"letter":"h","category":"Commitment","text":"Any new purchase or condemnation should be documented.","sop":true}]},{"code":"FMS.5","text":"The organisation manages medical equipment","elements":[{"letter":"a","category":"Commitment","text":"The organisation must also have plans for the medical equipment to meet the organisation's goals and values.","sop":false},{"letter":"b","category":"Commitment","text":"Documented medical equipment control is available.","sop":false},{"letter":"c","category":"CORE","text":"There must be a documented preventive maintenance plan in place for medical equipment.","sop":true},{"letter":"d","category":"Commitment","text":"Examination and calibration of medical equipment are done at regular intervals.","sop":false},{"letter":"e","category":"Commitment","text":"Only department-specific competent staff must handle the medical equipment.","sop":false},{"letter":"f","category":"Commitment","text":"Any new purchase or condemnation of medical equipment should be documented.","sop":true},{"letter":"g","category":"Commitment","text":"Medical device recalls are handled appropriately.","sop":true},{"letter":"h","category":"Achievement","text":"Medical equipment downtime is handled and analysed, and CAPA is done and documented.","sop":false}]},{"code":"FMS.6","text":"The organisation manages medical gas, vacuum and compressed air","elements":[{"letter":"a","category":"Commitment","text":"Procurement, handling, usage and replenishment of medical gases follow a guided protocol.","sop":true},{"letter":"b","category":"CORE","text":"Medical gas handling is done safely.","sop":false},{"letter":"c","category":"Commitment","text":"Piped medical gas, compressed air or vacuum installation is supported with prior testing and a contingency plan.","sop":true},{"letter":"d","category":"CORE","text":"Failure in any pipeline or gas supply is supported with a backup plan.","sop":false},{"letter":"e","category":"Commitment","text":"The resources available are checked for their efficiency periodically.","sop":false}]},{"code":"FMS.7","text":"The organisation plans and manages code red and non-code-red critical alerts effectively","elements":[{"letter":"a","category":"CORE","text":"In the event of a fire, the organisation has plans to predict, support, contain and safeguard patients and staff.","sop":true},{"letter":"b","category":"CORE","text":"Non-fire criticality is figured out and handled effectively.","sop":true},{"letter":"c","category":"Commitment","text":"The organisation has and displays an exit plan at times of emergencies (fire and non-fire).","sop":false},{"letter":"d","category":"Commitment","text":"Mock emergency setups and scenarios are conducted at least twice a year.","sop":false},{"letter":"e","category":"Commitment","text":"Fire-related equipment and infrastructure are managed under proper planning.","sop":true}]}]},"HRM":{"code":"HRM","name":"Human Resource Management","standards":[{"code":"HRM.1","text":"The organisation must plan its human resource requirements with a documented system available for it","elements":[{"letter":"a","category":"Commitment","text":"The human resource planning must be such that it meets the current and future requirements in order to provide optimal care.","sop":false},{"letter":"b","category":"CORE","text":"All kinds of staff, in the necessary numbers, are made available to meet the requirements of care.","sop":true},{"letter":"c","category":"Achievement","text":"The organisation must have a way to tackle human resource shortages, be it for a long time, short time or a sudden unplanned shortage.","sop":false},{"letter":"d","category":"Commitment","text":"The staff are provided with their JD (functional duties) in the organisation.","sop":false},{"letter":"e","category":"Commitment","text":"All new staff hired are checked for the authenticity of the information provided.","sop":false},{"letter":"f","category":"Commitment","text":"Each staff member must be made aware of their reporting hierarchy.","sop":true},{"letter":"g","category":"Achievement","text":"The hospital should have an exit interview system and address the concerns raised.","sop":false}]},{"code":"HRM.2","text":"Hiring staff has a defined structure","elements":[{"letter":"a","category":"CORE","text":"Staff hiring follows a documented guidance.","sop":true},{"letter":"b","category":"Commitment","text":"Medical fitness is ensured before hiring the staff.","sop":false},{"letter":"c","category":"CORE","text":"The code of conduct is established at the time of recruitment.","sop":false},{"letter":"d","category":"Commitment","text":"Documentation shall be made available for any administrative procedures that were involved during the hiring or appointment of the staff.","sop":true}]},{"code":"HRM.3","text":"The organisation provides induction training","elements":[{"letter":"a","category":"CORE","text":"All staff go through induction training.","sop":false},{"letter":"b","category":"Commitment","text":"Induction training must align with the organisation's goals and values.","sop":false},{"letter":"c","category":"Commitment","text":"Both patient and staff rights and responsibilities are informed.","sop":false},{"letter":"d","category":"Commitment","text":"Safety training is provided.","sop":false},{"letter":"e","category":"Commitment","text":"CPR training is provided.","sop":false},{"letter":"f","category":"Commitment","text":"Infection prevention and control training is provided.","sop":false},{"letter":"g","category":"Commitment","text":"Staff are trained on the services of the organisation.","sop":false},{"letter":"h","category":"Commitment","text":"Training on administrative protocols is provided.","sop":false},{"letter":"i","category":"Commitment","text":"Department-specific training for the staff recruited is also provided in the induction training.","sop":false},{"letter":"j","category":"Commitment","text":"Information system and security training is provided.","sop":false}]},{"code":"HRM.4","text":"The organisation focuses on internal staff training and development too","elements":[{"letter":"a","category":"CORE","text":"There must be documented guidance available to ensure that regular staff training and development is present and conducted.","sop":true},{"letter":"b","category":"Commitment","text":"The provided training record is made available at all times.","sop":false},{"letter":"c","category":"Commitment","text":"Training also covers times when there is a new system or a change in process or equipment.","sop":false},{"letter":"d","category":"Commitment","text":"Feedback is in place to obtain any concerns in the training provided.","sop":false},{"letter":"e","category":"Achievement","text":"The training provided is assessed.","sop":false},{"letter":"f","category":"Achievement","text":"The organisation must support regular professional training and development.","sop":false}]},{"code":"HRM.5","text":"Staff are trained on specific department activities","elements":[{"letter":"a","category":"Commitment","text":"Staff handling the procedures involving blood and body fluids are trained on the same.","sop":false},{"letter":"b","category":"Commitment","text":"Staff are trained on handling patients more prone to getting sick.","sop":false},{"letter":"c","category":"Commitment","text":"Restraint and safety control training is provided.","sop":false},{"letter":"d","category":"Commitment","text":"Professional communication training is provided.","sop":false},{"letter":"e","category":"CORE","text":"CPR training is provided to those who deal with patients directly.","sop":false},{"letter":"f","category":"Commitment","text":"Infection managing and control training is provided.","sop":false}]},{"code":"HRM.6","text":"Safety and quality training is provided to staff","elements":[{"letter":"a","category":"Commitment","text":"Training on organisation safety aspects is provided.","sop":false},{"letter":"b","category":"Commitment","text":"Risk management training is provided.","sop":false},{"letter":"c","category":"Commitment","text":"Incident reporting and handling training is provided.","sop":false},{"letter":"d","category":"Commitment","text":"Department-specific safety training is provided.","sop":false},{"letter":"e","category":"CORE","text":"Disaster management training is provided.","sop":false},{"letter":"f","category":"CORE","text":"Code red and non-code-red alerts handling training is provided.","sop":false},{"letter":"g","category":"Commitment","text":"Training on initiatives for improving the organisation's functional quality is provided.","sop":false}]},{"code":"HRM.7","text":"The organisation has an appraisal system","elements":[{"letter":"a","category":"Commitment","text":"All staff in the organisation have a performance appraisal.","sop":true},{"letter":"b","category":"Commitment","text":"The appraisal system is made known to staff in the induction training.","sop":false},{"letter":"c","category":"Commitment","text":"Predetermined criteria and performance scores shall determine the appraisal of the staff.","sop":false},{"letter":"d","category":"Commitment","text":"The appraisal system helps in the further development of the organisation.","sop":false},{"letter":"e","category":"Commitment","text":"Appraisal is done at regular intervals with valid documentation.","sop":false}]},{"code":"HRM.8","text":"The organisation has a grievance reporting and disciplinary system","elements":[{"letter":"a","category":"Commitment","text":"A documented protocol must guide the grievance and disciplinary activities.","sop":true},{"letter":"b","category":"Commitment","text":"All staff are aware of the grievance and disciplinary system.","sop":false},{"letter":"c","category":"Commitment","text":"The disciplinary policy is based on national justice principles.","sop":false},{"letter":"d","category":"CORE","text":"The organisation's disciplinary and grievance procedure must align with the existing laws.","sop":false},{"letter":"e","category":"Commitment","text":"All disciplinary cases are provided chances to appeal.","sop":false},{"letter":"f","category":"Commitment","text":"Grievances are addressed, analysed and actions are taken.","sop":false}]},{"code":"HRM.9","text":"The health and safety needs of staff are acknowledged and ensured","elements":[{"letter":"a","category":"Commitment","text":"The organisation shall have a policy to take care of the health and well-being of its staff.","sop":true},{"letter":"b","category":"Commitment","text":"All staff shall have a health checkup at least annually.","sop":false},{"letter":"c","category":"Commitment","text":"Staff injured at work are treated by the organisation.","sop":false},{"letter":"d","category":"CORE","text":"Workplace aggressions are prevented and handled properly by the organisation through a defined mechanism.","sop":true}]},{"code":"HRM.10","text":"Every staff member's personal information is made available by the HR department","elements":[{"letter":"a","category":"Commitment","text":"Personal information is stored in such a way that the privacy of the information is maintained.","sop":false},{"letter":"b","category":"Commitment","text":"The information contained must be about the staff's JD, qualification and medical fitness, etc.","sop":false},{"letter":"c","category":"Commitment","text":"Documentation of the staff's training and education is made available.","sop":false},{"letter":"d","category":"Commitment","text":"Evaluation and result records are also made available.","sop":false}]},{"code":"HRM.11","text":"All medical professionals have their credentials and privileges","elements":[{"letter":"a","category":"CORE","text":"Medical professionals who are authorised by law to treat patients are identified.","sop":false},{"letter":"b","category":"Commitment","text":"The identified medical professional's legal documents are maintained and updated as necessary.","sop":false},{"letter":"c","category":"Commitment","text":"The authenticity of the collected documents is verified.","sop":false},{"letter":"d","category":"CORE","text":"The medical professionals must be granted privileges based on their experience and qualification.","sop":false},{"letter":"e","category":"Commitment","text":"The facilities made available to a medical professional are known to them, as well as to every department of the organisation.","sop":false},{"letter":"f","category":"Commitment","text":"The care provided by the medical professional must be within the privileges granted to them.","sop":false}]},{"code":"HRM.12","text":"Nursing credentialing and privileging is also made available","elements":[{"letter":"a","category":"CORE","text":"Nursing professionals who are authorised by law to treat patients are identified.","sop":false},{"letter":"b","category":"Commitment","text":"The identified nursing professional's legal documents are maintained and updated as necessary.","sop":false},{"letter":"c","category":"Commitment","text":"The authenticity of the collected nursing documents is verified.","sop":false},{"letter":"d","category":"CORE","text":"The nursing professionals must be granted privileges based on their experience and qualification.","sop":false},{"letter":"e","category":"Commitment","text":"The facilities made available to a nursing professional are known to them, as well as to every department of the organisation.","sop":false},{"letter":"f","category":"Commitment","text":"The care provided by the nursing professional must be within the privileges granted to them.","sop":false}]},{"code":"HRM.13","text":"Para-clinical professionals' credentialing and privileging is also made available","elements":[{"letter":"a","category":"CORE","text":"Para-clinical professionals who are authorised by law to treat patients are identified.","sop":false},{"letter":"b","category":"Commitment","text":"The identified para-clinical professional's legal documents are maintained and updated as necessary.","sop":false},{"letter":"c","category":"CORE","text":"The para-clinical professionals must be granted privileges based on their experience and qualification.","sop":false},{"letter":"d","category":"Commitment","text":"The facilities made available to a para-clinical professional are known to them, as well as to every department of the organisation.","sop":false},{"letter":"e","category":"Commitment","text":"The care provided by the para-clinical professional must be within the privileges granted to them.","sop":false}]}]},"IMS":{"code":"IMS","name":"Information Management System","standards":[{"code":"IMS.1","text":"Information requirements of all members associated with the organisation, including patients, are met","elements":[{"letter":"a","category":"CORE","text":"The organisation figures out the information needs of all members associated with them, including the patients.","sop":true},{"letter":"b","category":"Commitment","text":"The information identified must be handled appropriately.","sop":true},{"letter":"c","category":"Commitment","text":"The information technology services are made available to meet the specific requirements in the organisation.","sop":false},{"letter":"d","category":"Commitment","text":"There must be a management plan for IT services in place.","sop":false},{"letter":"e","category":"Achievement","text":"There shall be a backup plan to sustain the provided IT services.","sop":false},{"letter":"f","category":"Commitment","text":"The organisation must make sure the information provided meets the requestor's requirements.","sop":false},{"letter":"g","category":"Commitment","text":"The organisation supports external databases, provided everything is done as per law and regulations.","sop":false},{"letter":"h","category":"Excellence","text":"The organisation adapts and implements digital technology for better efficiency.","sop":false}]},{"code":"IMS.2","text":"The organisation has a mechanism to manage data efficiently","elements":[{"letter":"a","category":"Commitment","text":"The data collection format is structured.","sop":false},{"letter":"b","category":"Commitment","text":"Data is checked and verified to meet the needs.","sop":false},{"letter":"c","category":"Commitment","text":"Requested information is provided within the defined time frame.","sop":false},{"letter":"d","category":"Commitment","text":"The organisation has a backup area where the data can be stored and retrieved.","sop":true},{"letter":"e","category":"Commitment","text":"There must be dedicated staff who handle and deliver data.","sop":false}]},{"code":"IMS.3","text":"All the patients under the organisation's care must have a precise medical record","elements":[{"letter":"a","category":"CORE","text":"Patients must have a unique registration number for better identification.","sop":false},{"letter":"b","category":"Commitment","text":"Information in the medical record is captured and stored.","sop":true},{"letter":"c","category":"CORE","text":"The information stored must be in such a way that it contains the entire cycle of patient care provided in the hospital.","sop":false},{"letter":"d","category":"Commitment","text":"Data entries into the medical record are done only by those authorised by the organisation.","sop":true},{"letter":"e","category":"Commitment","text":"All the entered records are acknowledged, dated and timed.","sop":false},{"letter":"f","category":"Commitment","text":"Data is captured in such a way that the details of the person entering it are made available.","sop":false},{"letter":"g","category":"Commitment","text":"The abbreviations used in the records are authorised and approved by the organisation.","sop":false}]},{"code":"IMS.4","text":"The medical record must display the required episode content","elements":[{"letter":"a","category":"Commitment","text":"The medical record must explain why the patient was admitted, how they were treated and every such piece of information throughout the patient care.","sop":false},{"letter":"b","category":"Commitment","text":"All information regarding consultation, cross-consultation or assessment is made available there.","sop":false},{"letter":"c","category":"Commitment","text":"All the test results must be available in the medical record.","sop":false},{"letter":"d","category":"Commitment","text":"Any surgical procedures performed are mentioned in the medical record.","sop":false},{"letter":"e","category":"Commitment","text":"Patient transfers are mentioned in the medical record.","sop":false},{"letter":"f","category":"Commitment","text":"The signed discharge summary is made available in the medical record.","sop":false},{"letter":"g","category":"Commitment","text":"Death case records must also include the cause of death information.","sop":false},{"letter":"h","category":"Commitment","text":"All the patient care providers must be able to access the previous and current patient information stored.","sop":false}]},{"code":"IMS.5","text":"Patient data safety is ensured by the organisation","elements":[{"letter":"a","category":"CORE","text":"Confidentiality of patient data is ensured by the organisation.","sop":true},{"letter":"b","category":"CORE","text":"Data authenticity is ensured by the organisation.","sop":false},{"letter":"c","category":"CORE","text":"Data security is ensured by the organisation.","sop":true},{"letter":"d","category":"Achievement","text":"To ensure that data authenticity, confidentiality and security are maintained, adequate technology is adopted.","sop":false},{"letter":"e","category":"Commitment","text":"If any health information of the patient is to be disclosed, it is disclosed only upon authorisation of the patient or as required by law.","sop":false},{"letter":"f","category":"Commitment","text":"Any request to access a patient record is addressed with a guiding protocol.","sop":true}]},{"code":"IMS.6","text":"The organisation ensures the availability of necessary records and the retention parameters for the same","elements":[{"letter":"a","category":"CORE","text":"The organisation has a document control mechanism.","sop":true},{"letter":"b","category":"CORE","text":"Patient records are managed by the hospital as per established protocol.","sop":true},{"letter":"c","category":"Commitment","text":"Retention should not compromise on patient data confidentiality and security.","sop":false},{"letter":"d","category":"Commitment","text":"Destruction of records follows a documented guidance.","sop":true}]},{"code":"IMS.7","text":"Medical records are reviewed by the organisation","elements":[{"letter":"a","category":"CORE","text":"Records are reviewed at regular intervals.","sop":false},{"letter":"b","category":"Commitment","text":"Analysing the record data follows statistical methods.","sop":false},{"letter":"c","category":"Commitment","text":"Only authorised individuals conduct record data analysis.","sop":false},{"letter":"d","category":"Commitment","text":"Parameters are set to analyse the record data.","sop":false},{"letter":"e","category":"Commitment","text":"Both active as well as checked-out patient record data must be checked and analysed.","sop":false},{"letter":"f","category":"Commitment","text":"The analysis must figure out any lacunae in the medical information, which must be documented.","sop":false},{"letter":"g","category":"Commitment","text":"CAPA is done for the identified lacunae.","sop":true}]}]}},"official":{"AAC":{"standards":13,"elements":87,"core":6,"commitment":68,"achievement":9,"excellence":4},"COP":{"standards":20,"elements":136,"core":13,"commitment":107,"achievement":12,"excellence":4},"MOM":{"standards":11,"elements":68,"core":13,"commitment":48,"achievement":6,"excellence":1},"PRE":{"standards":8,"elements":52,"core":12,"commitment":32,"achievement":7,"excellence":1},"IPC":{"standards":8,"elements":49,"core":13,"commitment":33,"achievement":3,"excellence":0},"PSQ":{"standards":7,"elements":46,"core":8,"commitment":28,"achievement":7,"excellence":3},"ROM":{"standards":6,"elements":37,"core":4,"commitment":23,"achievement":8,"excellence":2},"FMS":{"standards":7,"elements":43,"core":11,"commitment":29,"achievement":2,"excellence":1},"HRM":{"standards":13,"elements":76,"core":16,"commitment":56,"achievement":4,"excellence":0},"IMS":{"standards":7,"elements":45,"core":9,"commitment":33,"achievement":2,"excellence":1}},"totals":{"standards":100,"elements":639,"core":105,"commitment":457,"achievement":60,"excellence":17}};
